@Service
public class BillingService {

    @Autowired
    private AuditLogService auditLogService;

    @Autowired
    private InvoiceRepository invoiceRepository;

    @Transactional(propagation = Propagation.REQUIRED)
    public void processInvoice(Invoice invoice) {
        invoiceRepository.save(invoice);
        try {
            // Even if audit fails, we want the invoice persisted independently
            auditLogService.logActionRequiresNew("INVOICE_PROCESSED");
        } catch (Exception e) {
            // Log error but do not fail invoice processing
        }
    }
}

@Service
public class AuditLogService {

    @Autowired
    private AuditRepository auditRepository;

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void logActionRequiresNew(String action) {
        auditRepository.save(new AuditLog(action));
        // If this throws an exception, only the audit record rolls back
    }
}
